{{ api_model('fiscal_initial_expenditure_budget_lines') }}
select l.fiscal_line_id,l.dataset_id,'b-' || sha256(l.fiscal_line_id) as budget_item_id,l.source_row,a.value as amount,l.consolidation,l.counterpart_fund,l.cofog_code,l.cofog_status,l.cofog_basis from {{ ref('int_fiscal_lines') }} l join {{ ref('int_fiscal_datasets') }} d using(dataset_id) join {{ ref('int_fiscal_amounts') }} a using(fiscal_line_id) where d.direction='expenditure' and d.document_kind='budget' and a.phase='approved' order by fiscal_line_id
